  padding:44px 52px 40px;border-bottom:1.5px solid var(--border);
  position:relative;overflow:hidden;
}
.case-num{
  font-size:100px;font-weight:900;line-height:1;opacity:0.04;
  position:absolute;top:8px;right:36px;letter-spacing:-4px;pointer-events:none;
}
.case-tag{
  display:inline-block;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;
  padding:5px 16px;border-radius:100px;margin-bottom:16px;font-weight:700;
  background:rgba(212,105,42,0.08);color:var(--accent);
}
.case-title{font-size:clamp(22px,3vw,32px);font-weight:800;letter-spacing:-0.3px;margin-bottom:6px}
.case-subtitle{font-size:16px;color:var(--text-dim);font-weight:500}
.case-body{padding:48px 52px}

/* STORY BLOCK */
.story-block{
  border-radius:16px;padding:32px 36px;margin-bottom:28px;
  position:relative;background:var(--surface2);border:1px solid var(--border);
}
.story-block .scene{
  font-size:15px;color:var(--text-muted);font-weight:600;
  letter-spacing:1px;text-transform:uppercase;margin-bottom:12px;
  padding-left:102px;position:relative;
}
.story-block .scene::before{
  content:'';position:absolute;left:0;top:50%;transform:translateY(-50%);
  width:88px;height:88px;
  background:url(assets/analysis-badge.jpg) no-repeat center;
  background-size:contain;
}
.story-block .narrative{
  font-size:19px;color:var(--text);line-height:1.9;font-weight:500;margin-bottom:14px;
}
.story-block .narrative:last-child{margin-bottom:0}
.story-block em{
  font-style:italic;color:var(--accent2);
  background:rgba(212,105,42,0.06);padding:1px 5px;border-radius:4px;
}

/* CHAT BUBBLE — 88px avatar */
.chat-bubble{display:flex;gap:14px;align-items:flex-start;margin:14px 0}
.chat-avatar{
  flex-shrink:0;width:88px;height:88px;border-radius:50%;overflow:hidden;
  display:flex;align-items:center;justify-content:center;
  box-shadow:0 3px 10px rgba(0,0,0,0.15);
}
.chat-avatar img{width:100%;height:100%;object-fit:cover}
.chat-avatar.coach{border:3px solid rgba(212,105,42,0.40)}
.chat-avatar.ai{border:3px solid rgba(74,139,112,0.40)}
.chat-content{flex:1;min-width:0}
.chat-name{
  font-size:12px;font-weight:700;letter-spacing:1px;text-transform:uppercase;
  margin-bottom:5px;color:var(--text-muted);
}
.chat-text{
  background:var(--surface2);border:1.5px solid var(--border);
  border-radius:0 18px 18px 18px;padding:14px 20px;

